import {ToolRegistry} from './registry.js';

describe('ToolRegistry.execute input validation', () => {
  it('returns a ToolResponse naming a missing required property and skips the executor', async () => {
    const registry = new ToolRegistry();
    let executorCalls = 0;
    registry.register(
      {
        name: 'get_weather',
        description: 'Get weather for a location',
        inputSchema: {
          type: 'object',
          properties: {location: {type: 'string'}},
          required: ['location'],
        },
      },
      async () => {
        executorCalls += 1;
        return 'sunny';
      }
    );

    const response = await registry.execute('get_weather', {});

    expect({executorCalls, result: response.result}).toEqual({
      executorCalls: 0,
      result: expect.stringContaining('location'),
    });
  });
});
